private boolean limitRegenIfFreezing(GameRules gameRules, GameRules.Key<GameRules.BooleanValue> key)
{
    checkFrozenHealth:
    if (key == GameRules.RULE_NATURAL_REGENERATION)
    {
        Map<TempEffectType<?>, TempEffect> tempEffects = EntityTempManager.getTemperatureCap(STORED_PLAYER).map(ITemperatureCap::getTempEffects).orElse(new HashMap<>());
        TempEffect freezeHealingEffect = tempEffects.get(TempEffectInit.FREEZE_HEALING.get());
        if (freezeHealingEffect != null)
        {
            double effect = freezeHealingEffect.getEffectFactor(STORED_PLAYER);
            double heartsFreezePercentage = ConfigSettings.HEARTS_FREEZING_PERCENTAGE.get();
            if (heartsFreezePercentage == 0)
            {   break checkFrozenHealth;
            }

            float maxHealth = STORED_PLAYER.getMaxHealth();

            float maxFrozenHealth = (float) (maxHealth * heartsFreezePercentage);
            float frozenHealth = Math.round(CSMath.blend(0, maxFrozenHealth, effect, 0, 1));
            float unfrozenHealth = maxHealth - frozenHealth;
            if (STORED_PLAYER.getHealth() >= unfrozenHealth)
            {   return false;
            }
        }
    }
    return gameRules.getBoolean(key);
}

public void onRenderHeart(RenderHeartEvent event)
{
    LivingEntity player = Minecraft.getInstance().player;
    if (!this.test(player)) return;
    if (!ConfigSettings.SHOW_FROZEN_HEALTH.get()) return;

    Gui.HeartType heartType = event.getHeartType();
    boolean halfHeart = event.isHalfHeart();
    int x = event.getX();
    int y = event.getY();
    // This check ensures that this only gets called once per heart
    if (heartType == Gui.HeartType.CONTAINER)
    {   heartIndex += 1;
    }

    double effect = this.getEffectFactor(player);
    double heartsFreezePercentage = ConfigSettings.HEARTS_FREEZING_PERCENTAGE.get();
    if (heartsFreezePercentage == 0) return;

    float maxHealth = player.getMaxHealth();
    boolean isHardcore = player.level().getLevelData().isHardcore();

    float maxFrozenHealth = (float) (maxHealth * heartsFreezePercentage);
    if (maxFrozenHealth == 0) return;

    int frozenHealth = (int) Math.round(CSMath.blend(0, maxHealth * heartsFreezePercentage, effect, 0, 1));
    int frozenHearts = Math.round(frozenHealth / 2f);
    boolean partialFrozen = frozenHealth % 2 == 1 && heartIndex == frozenHearts;

    // Render frozen hearts
    if (heartIndex <= frozenHearts)
    {
        int u, v;
        if (heartType == Gui.HeartType.CONTAINER)
        {   u = 14;
            v = partialFrozen ? 14 : 0;
        }
        else
        {   u = isHardcore ? 7 : 0;
            v = partialFrozen ? halfHeart ? 21 : 14 : halfHeart ? 7 : 0;
        }
        event.getGuiGraphics().blit(HEART_TEXTURE, x + 1, y + 1, u, v, 7, 7, 21, 28);
    }
}

public void resetHeartIndex(TickEvent.RenderTickEvent event)
{
    if (event.phase == TickEvent.Phase.START)
    {   heartIndex = 0;
    }
}

